-- Administrative facts only; behavioral/security policy remains in application code.
CREATE TABLE public.community_knowledge (
 topic_id text PRIMARY KEY CHECK (topic_id ~ '^[a-z][a-z0-9_-]{1,47}$'),
 title text NOT NULL CHECK (char_length(btrim(title)) BETWEEN 2 AND 100),
 draft_content text NOT NULL CHECK (char_length(btrim(draft_content)) BETWEEN 1 AND 2000),
 published_content text CHECK (char_length(btrim(published_content)) BETWEEN 1 AND 2000),
 is_active boolean NOT NULL DEFAULT false,
 revision integer NOT NULL DEFAULT 1,
 updated_by uuid REFERENCES public.profiles(id) ON DELETE SET NULL,
 updated_at timestamptz NOT NULL DEFAULT now(),
 published_at timestamptz,
 CHECK (NOT is_active OR published_content IS NOT NULL)
);
ALTER TABLE public.community_knowledge ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.community_knowledge FROM PUBLIC, anon, authenticated;
GRANT SELECT ON public.community_knowledge TO authenticated, service_role;
CREATE POLICY "Active admin reads knowledge" ON public.community_knowledge FOR SELECT TO authenticated USING (public.is_admin());

CREATE FUNCTION public.write_community_knowledge(p_operation text, p_topic_id text, p_title text, p_facts text, p_revision integer)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $$
DECLARE previous public.community_knowledge; current_row public.community_knowledge;
BEGIN
 IF auth.uid() IS NULL OR NOT public.is_admin() THEN RAISE EXCEPTION 'Admin required' USING ERRCODE='42501'; END IF;
 PERFORM pg_advisory_xact_lock(2061010, 1);
 SELECT * INTO previous FROM public.community_knowledge WHERE topic_id=p_topic_id FOR UPDATE;
 IF (previous.topic_id IS NULL AND p_revision<>0) OR (previous.topic_id IS NOT NULL AND previous.revision IS DISTINCT FROM p_revision) THEN
  RAISE EXCEPTION 'Revision conflict' USING ERRCODE='40001';
 END IF;
 IF p_operation='save' THEN
  IF p_facts ~* '(sk-[a-z0-9_-]{12,}|Bearer[[:space:]]+[a-z0-9._-]+|eyJ[a-z0-9_-]+\.[a-z0-9_-]+\.[a-z0-9_-]+)' THEN RAISE EXCEPTION 'Credentials forbidden' USING ERRCODE='22023'; END IF;
  IF previous.topic_id IS NULL THEN
   IF (SELECT count(*) FROM public.community_knowledge)>=40 THEN RAISE EXCEPTION 'Topic limit' USING ERRCODE='22023'; END IF;
   INSERT INTO public.community_knowledge(topic_id,title,draft_content,updated_by) VALUES(p_topic_id,btrim(p_title),btrim(p_facts),auth.uid());
  ELSE
   UPDATE public.community_knowledge SET title=btrim(p_title),draft_content=btrim(p_facts),revision=revision+1,updated_by=auth.uid(),updated_at=now() WHERE topic_id=p_topic_id;
  END IF;
 ELSIF p_operation IN ('publish','pause','resume') AND previous.topic_id IS NOT NULL THEN
  UPDATE public.community_knowledge SET
   published_content=CASE WHEN p_operation='publish' THEN draft_content ELSE published_content END,
   is_active=p_operation<>'pause',
   published_at=CASE WHEN p_operation='publish' THEN now() ELSE published_at END,
   revision=revision+1,updated_by=auth.uid(),updated_at=now() WHERE topic_id=p_topic_id;
 ELSE RAISE EXCEPTION 'Invalid operation' USING ERRCODE='22023'; END IF;
 IF (SELECT coalesce(sum(char_length(published_content)),0) FROM public.community_knowledge WHERE is_active)>24000 THEN
  RAISE EXCEPTION 'Knowledge limit' USING ERRCODE='22023';
 END IF;
 SELECT * INTO current_row FROM public.community_knowledge WHERE topic_id=p_topic_id;
 INSERT INTO public.audit_logs(user_id,action,entity_type,details) VALUES(auth.uid(),'community_knowledge_'||p_operation,'community_knowledge',
  jsonb_build_object('topic_id',p_topic_id,'before',to_jsonb(previous),'after',to_jsonb(current_row)));
END $$;
REVOKE ALL ON FUNCTION public.write_community_knowledge(text,text,text,text,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.write_community_knowledge(text,text,text,text,integer) TO authenticated;

INSERT INTO public.community_knowledge(topic_id,title,draft_content,published_content,is_active,published_at) VALUES
('beta','Fase de testes','Clube da Sueca está em beta gratuito com créditos fictícios, sem valor monetário. Todos os saldos serão repostos a zero no lançamento oficial. A licença para dinheiro real em Moçambique e o prestador de pagamentos estão pendentes. Sem data de lançamento confirmada.','Clube da Sueca está em beta gratuito com créditos fictícios, sem valor monetário. Todos os saldos serão repostos a zero no lançamento oficial. A licença para dinheiro real em Moçambique e o prestador de pagamentos estão pendentes. Sem data de lançamento confirmada.',true,now()),
('rules','Regras da Sueca','Sueca: 4 jogadores em 2 equipas de 2, parceiros frente a frente. Baralho de 40 cartas sem 8,9,10; 10 cartas por jogador e 10 vazas. Ás=11, 7=10, Rei=4, Valete=3, Dama=2 pontos; 6,5,4,3,2=0. Força: A,7,K,J,Q,6,5,4,3,2. Total 120 pontos; 61 ou mais vence; 60-60 é empate.','Sueca: 4 jogadores em 2 equipas de 2, parceiros frente a frente. Baralho de 40 cartas sem 8,9,10; 10 cartas por jogador e 10 vazas. Ás=11, 7=10, Rei=4, Valete=3, Dama=2 pontos; 6,5,4,3,2=0. Força: A,7,K,J,Q,6,5,4,3,2. Total 120 pontos; 61 ou mais vence; 60-60 é empate.',true,now()),
('trump','Trunfo e vazas','O trunfo é definido no início e indicado na mesa. Tens de assistir ao naipe de saída se tiveres cartas desse naipe. Sem esse naipe podes cortar com trunfo ou baldar. Ganha o trunfo mais forte jogado; sem trunfo, a carta mais forte do naipe de saída. O vencedor da vaza inicia a próxima. Só podes jogar na tua vez, com cartas da tua mão.','O trunfo é definido no início e indicado na mesa. Tens de assistir ao naipe de saída se tiveres cartas desse naipe. Sem esse naipe podes cortar com trunfo ou baldar. Ganha o trunfo mais forte jogado; sem trunfo, a carta mais forte do naipe de saída. O vencedor da vaza inicia a próxima. Só podes jogar na tua vez, com cartas da tua mão.',true,now()),
('modes','Demo, treino e tutorial','Demo sem conta pela página inicial (/demo). Treino gratuito contra bots no menu Treino (/dashboard/training). Tutorial no menu Tutorial (/dashboard/tutorial). Treino separado das mesas online de quatro jogadores.','Demo sem conta pela página inicial (/demo). Treino gratuito contra bots no menu Treino (/dashboard/training). Tutorial no menu Tutorial (/dashboard/tutorial). Treino separado das mesas online de quatro jogadores.',true,now()),
('tables','Mesas online','Menu Jogar (/dashboard/play): criar ou entrar numa mesa com saldo suficiente. Entradas disponíveis: 50,100,250,500,1000 créditos fictícios por jogador. Começa com quatro jogadores; há convites para amigos. Enquanto a mesa aguarda, sair permite devolver a entrada. Não prometer reembolso por abandonar partida iniciada.','Menu Jogar (/dashboard/play): criar ou entrar numa mesa com saldo suficiente. Entradas disponíveis: 50,100,250,500,1000 créditos fictícios por jogador. Começa com quatro jogadores; há convites para amigos. Enquanto a mesa aguarda, sair permite devolver a entrada. Não prometer reembolso por abandonar partida iniciada.',true,now()),
('results','Resultados e entradas','Pote soma as quatro entradas. Vitória: taxa simulada de 20%, arredondada ao cêntimo, restante dividido igualmente pelos dois vencedores. Entrada 100: pote 400, cada vencedor recebe 160 créditos fictícios (ganho líquido 60). Empate: cada jogador recebe a entrada de volta, sem taxa. Resultado e crédito calculados no servidor.','Pote soma as quatro entradas. Vitória: taxa simulada de 20%, arredondada ao cêntimo, restante dividido igualmente pelos dois vencedores. Entrada 100: pote 400, cada vencedor recebe 160 créditos fictícios (ganho líquido 60). Empate: cada jogador recebe a entrada de volta, sem taxa. Resultado e crédito calculados no servidor.',true,now()),
('mobile','Jogar no telemóvel','Mobile: toca na carta para selecionar e novamente para jogar; segue as indicações da tua vez e cartas permitidas. Contador indica prazo; ao esgotar, o servidor permite jogada automática válida. Problemas de ligação: restabelece ligação e reabre a mesma mesa; se persistirem, regista no Suporte. Não garantir recuperação/reembolso.','Mobile: toca na carta para selecionar e novamente para jogar; segue as indicações da tua vez e cartas permitidas. Contador indica prazo; ao esgotar, o servidor permite jogada automática válida. Problemas de ligação: restabelece ligação e reabre a mesma mesa; se persistirem, regista no Suporte. Não garantir recuperação/reembolso.',true,now()),
('wallet','Carteira e créditos','Todas as carteiras usam MZN (metical moçambicano), sempre com créditos fictícios no beta. Carteira (/dashboard/wallet) > Adicionar créditos de teste (/dashboard/wallet/deposit): adição gratuita de 50 a 10000 créditos inteiros por operação, limite de carteira 100000. Não há cobrança, depósitos de dinheiro, M-Pesa, e-Mola, pagamentos móveis nem levantamentos ativos no beta. Créditos não viram dinheiro e serão resetados no lançamento.','Todas as carteiras usam MZN (metical moçambicano), sempre com créditos fictícios no beta. Carteira (/dashboard/wallet) > Adicionar créditos de teste (/dashboard/wallet/deposit): adição gratuita de 50 a 10000 créditos inteiros por operação, limite de carteira 100000. Não há cobrança, depósitos de dinheiro, M-Pesa, e-Mola, pagamentos móveis nem levantamentos ativos no beta. Créditos não viram dinheiro e serão resetados no lançamento.',true,now()),
('account','Conta e senha','Registo exige 18 anos e confirmação de email. Login por email e senha com verificação de segurança. Minha Conta (/dashboard/profile) permite editar perfil, username e avatar. Para recuperar senha: Esqueceu a password? no login (/forgot-password), pede novo email e usa o link mais recente, de utilização única e sujeito a expiração. Nunca partilhar senha, PIN, tokens ou links de recuperação no chat.','Registo exige 18 anos e confirmação de email. Login por email e senha com verificação de segurança. Minha Conta (/dashboard/profile) permite editar perfil, username e avatar. Para recuperar senha: Esqueceu a password? no login (/forgot-password), pede novo email e usa o link mais recente, de utilização única e sujeito a expiração. Nunca partilhar senha, PIN, tokens ou links de recuperação no chat.',true,now()),
('history','Histórico','Histórico (/dashboard/history): partidas concluídas e movimentos da carteira com paginação. Movimentos do beta são fictícios. O bot não consulta histórico nem saldo particular.','Histórico (/dashboard/history): partidas concluídas e movimentos da carteira com paginação. Movimentos do beta são fictícios. O bot não consulta histórico nem saldo particular.',true,now()),
('bonuses','Bónus e promoções','Bónus (/dashboard/bonuses): ofertas disponíveis, bónus do utilizador e resgate de códigos promocionais. Condições e prazos dependem da oferta exibida. Não inventar códigos, campanhas, valores ou níveis VIP. Bónus do beta são fictícios e não levantáveis.','Bónus (/dashboard/bonuses): ofertas disponíveis, bónus do utilizador e resgate de códigos promocionais. Condições e prazos dependem da oferta exibida. Não inventar códigos, campanhas, valores ou níveis VIP. Bónus do beta são fictícios e não levantáveis.',true,now()),
('affiliates','Afiliados','Afiliados (/dashboard/affiliates): candidatura sujeita a análise, links de referência e acompanhamento de referências/comissões. Comissões fictícias no beta, pagamentos indisponíveis. Não garantir aprovação, percentagem individual, rendimentos ou pagamento.','Afiliados (/dashboard/affiliates): candidatura sujeita a análise, links de referência e acompanhamento de referências/comissões. Comissões fictícias no beta, pagamentos indisponíveis. Não garantir aprovação, percentagem individual, rendimentos ou pagamento.',true,now()),
('community','Comunidade e robô','Chat da Comunidade público para jogadores autenticados, mostra últimas 10 mensagens. Sueca Bot é assistente automático para dúvidas gerais da plataforma; não interrompe conversas entre jogadores. Não é atendimento privado; não vê cartas escondidas nem altera jogos, saldos ou contas.','Chat da Comunidade público para jogadores autenticados, mostra últimas 10 mensagens. Sueca Bot é assistente automático para dúvidas gerais da plataforma; não interrompe conversas entre jogadores. Não é atendimento privado; não vê cartas escondidas nem altera jogos, saldos ou contas.',true,now()),
('support','Atendimento e suporte','Suporte (/dashboard/support): abrir e acompanhar pedidos privados. Estados Em espera, Em resolução e Resolvido. Podes continuar a responder a um pedido resolvido; administração pode alterar estado. Sem prazo garantido no beta. Problemas individuais, denúncias e contestação de saldo/partida: usar Suporte sem dados pessoais no chat. Bot não abre pedidos nem garante aviso a humano.','Suporte (/dashboard/support): abrir e acompanhar pedidos privados. Estados Em espera, Em resolução e Resolvido. Podes continuar a responder a um pedido resolvido; administração pode alterar estado. Sem prazo garantido no beta. Problemas individuais, denúncias e contestação de saldo/partida: usar Suporte sem dados pessoais no chat. Bot não abre pedidos nem garante aviso a humano.',true,now()),
('security','Segurança','Jogadas, resultados e baralhamento online validados no servidor. Não afirmar licença aprovada, certificação, jogo infalível ou deteção garantida de conluio. Não explicar exploração de falhas, batota ou manipulação de resultados; encaminhar denúncias ao Suporte.','Jogadas, resultados e baralhamento online validados no servidor. Não afirmar licença aprovada, certificação, jogo infalível ou deteção garantida de conluio. Não explicar exploração de falhas, batota ou manipulação de resultados; encaminhar denúncias ao Suporte.',true,now()),
('domains','Domínios e emails','Mesma plataforma em clubedasueca.co.mz (Moçambique), clubedasueca.pt, clubedasueca.com, clubedasueca.com.br. Email de autenticação usa remetente .pt ou .co.mz conforme origem suportada. Não inventar emails, telefones ou canais externos de suporte.','Mesma plataforma em clubedasueca.co.mz (Moçambique), clubedasueca.pt, clubedasueca.com, clubedasueca.com.br. Email de autenticação usa remetente .pt ou .co.mz conforme origem suportada. Não inventar emails, telefones ou canais externos de suporte.',true,now());
